async def api_me(req):
    """Profil: ism + har bir o'yin bo'yicha statistika + bot username."""
    u = auth(req.query)
    if not u:
        return web.json_response(dict(ok=False, m="Avtorizatsiya xato"))
    fr_reg(u[0], u[1], _tg_un.get(u[0]))
    with _stats_mem_lock:
        st = ensure_stats(u[0], u[1])
        ensure_weekly(st)
        games_st = {g: st.get(g, {"w": 0, "l": 0, "pts": 0}) for g in GAMES}
        hist = list(reversed(st.get("history", [])[-10:]))
        mine_h2h = h2h(st)
        di, av, cups = daily_info(st), ach_view(st), st.get("cups", 0)
    rank = weekly_ranking()
    pos = next((i + 1 for i, r in enumerate(rank) if r[0] == u[0]), None)
    top = [dict(n=r[1], w=r[2], pts=r[3], me=(r[0] == u[0])) for r in rank[:10]]
    return web.json_response(dict(
        ok=True, name=u[1],
        w=st.get("w", 0), l=st.get("l", 0), pts=st.get("pts", 0),
        games=games_st, bot=BOT_USERNAME,
        hist=hist, h2h=mine_h2h, week=current_week(), top=top, daily=di, ach=av, cups=cups,
        wme=dict(rank=pos, w=st["weekly"]["w"], pts=st["weekly"]["pts"], total=len(rank)),
        **fr_info(u[0])
    ))


