def bg(coro):
    """Telegram API javobini kutmasdan fonda ishga tushirish."""
    t = asyncio.create_task(coro)
    _bg_tasks.add(t)
    t.add_done_callback(_bg_tasks.discard)


async def announce(room):
    if not BOT:
        return
    title = GAME_TITLES.get(room.game, "Card Game")
    for p in room.players:
        if p.is_bot:
            continue
        try:
            await BOT.send_message(p.id, f"🎴 {title} boshlandi! Xona {room.code}",
                                   reply_markup=wa_kb(room.code))
        except Exception:
            log.warning("xabar yuborilmadi: %s", p.id)


# REVIEW2 FIX #3: Xona o'chirilganda barcha background task'larni bekor qilish va WS ulanishlarni yopish
def _cancel_room_tasks(r):
    for attr in ("_wd_task", "bot_task", "_color_timer", "_tour_task"):
        t = getattr(r, attr, None)
        if t and not t.done():
            t.cancel()
        setattr(r, attr, None)


def _cleanup_room_sync(r):
    _cancel_room_tasks(r)
    for ws_set in list(r.socks.values()):
        for ws in list(ws_set):
            coro = ws.close()
            try:
                bg(coro)
            except RuntimeError:           # event loop yopiq — coroutine'ni toza yopamiz
                coro.close()
            except Exception:
                coro.close()
    r.socks.clear()


async def _cleanup_room_async(r):
    _cancel_room_tasks(r)
    for ws_set in list(r.socks.values()):
        for ws in list(ws_set):
            try:
                await ws.close()
            except Exception:
                pass
    r.socks.clear()


def new_room(uid, name, game="bura"):
    for c, r in list(rooms.items()):
        if time.time() - r.created > 6 * 3600:
            _cleanup_room_sync(r)
            rooms.pop(c, None)
    code = "".join(random.choices(string.digits, k=6))
    while code in rooms:
        code = "".join(random.choices(string.digits, k=6))
    cls = ROOM_CLASSES.get(game, BurkozyolRoom)
    rooms[code] = cls(code, uid, name)
    return code


