def _hist_lines(st, n=10):
    out = []
    for h in reversed(st.get("history", [])[-n:]):
        mark = "✅" if h.get("w") else "❌"
        out.append(f"{mark} {GAME_TITLES.get(h.get('g'), h.get('g'))}" + (f" vs {h['op']}" if h.get("op") else ""))
    return out


@router.message(Command("profil"))
async def h_profil(m: Message):
    fr_reg(m.from_user.id, m.from_user.first_name, m.from_user.username)
    with _stats_mem_lock:
        st = ensure_stats(m.from_user.id, m.from_user.first_name)
        wk = dict(ensure_weekly(st))
        hl, hh = _hist_lines(st), h2h(st, 3)
        di, av, cups = daily_info(st), ach_view(st), st.get("cups", 0)
        lines = [f"👤 {st['name']}", f"🏆 Jami g'alaba: {st['w']} | 💔 Mag'lubiyat: {st['l']} | ⭐ Ball: {st['pts']}",
                 f"📅 Bu hafta: {wk['w']}W / {wk['l']}L ({wk['pts']} ball)\n"]
        for g in GAMES:
            gs = st.get(g, {"w": 0, "l": 0, "pts": 0})
            lines.append(f"• {GAME_TITLES[g]}: {gs['w']}W / {gs['l']}L ({gs['pts']} ball)")
    lines += ["", daily_text(di) + (f" | 🏆 Turnir kubogi: {cups}" if cups else "")]
    lines += ["", f"🏅 Yutuqlar ({sum(1 for a in av if a['got'])}/{len(av)}):"]
    lines += [f"{a['ic']} {a['n']}" if a["got"] else f"🔒 {a['n']} — {a['d']}" for a in av]
    if hl:
        lines += ["", "🕘 Oxirgi o'yinlar:"] + hl
    if hh:
        lines += ["", "🆚 Yakkama-yakka: " + " | ".join(f"{r['op']} {r['w']}-{r['l']}" for r in hh)]
    await m.answer("\n".join(lines))


@router.message(Command("top"))
async def h_top(m: Message):
    fr_reg(m.from_user.id, m.from_user.first_name, m.from_user.username)
    rank = weekly_ranking()
    if not rank:
        return await m.answer(f"📅 {current_week()}: bu hafta hali hech kim yutmagan. Birinchi bo'ling! 🏁")
    medals = ["🥇", "🥈", "🥉"]
    lines = [f"🏆 Haftalik reyting ({current_week()})"]
    for i, (uid, name, w, pts) in enumerate(rank[:10]):
        you = " ← siz" if uid == m.from_user.id else ""
        lines.append(f"{medals[i] if i < 3 else str(i + 1) + '.'} {name} — {w} G / {pts} ball{you}")
    pos = next((i + 1 for i, r in enumerate(rank) if r[0] == m.from_user.id), None)
    if pos and pos > 10:
        lines.append(f"…\n{pos}. siz — {rank[pos - 1][2]} G / {rank[pos - 1][3]} ball")
    await m.answer("\n".join(lines))


def _arg_user(command) -> str:
    return (command.args or "").strip().split()[0].lstrip("@") if (command.args or "").strip() else ""


